#!/usr/bin/env bash
# Réglages du site + chapitre « Les réglages du site » :
#   - pied de page : accroche, coordonnées et RNA / SIRET lus dans les Réglages (comme « Nous contacter ») ;
#   - logo servi par le site lui-même, mis en cache par version (la redirection signée pouvait expirer) ;
#   - Réglages : champ « Langue par défaut » retiré (il n'avait aucun effet) ;
#   - nouveau chapitre 5.2 et raccords.
# Prérequis : apply-titres-constructeur.sh.
# Usage (racine du repo) : bash apply-reglages-site.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/contenu/reglages-du-site.mdx" 2>/dev/null | grep -qF "title: \"Les réglages du site\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Le constructeur de pages\"" "apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-titres-constructeur.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" "apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/src/app/(admin)/dashboard/settings/page.tsx" "apps/web/src/app/api/media/site-logo/route.ts" "apps/web/src/features/app-shell/Footer.tsx" "apps/web/src/features/app-shell/clubInfo.ts" "packages/backend/src/modules/siteSettings/router.ts" "prisma/schema.prisma")
CREATED=("apps/web/content/docs/dev/contenu/reglages-du-site.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les réglages du site\"" "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/contenu"
