trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
réglages du site : pied de page sur SiteSettings, logo servi en même origine ; doc « Les réglages du site »

- Footer : accroche, coordonnées (adresse, téléphones joignables en appel,
  e-mail) et RNA / SIRET lus dans SiteSettings, comme « Nous contacter » ;
  clubInfo.ts ne garde que réseaux sociaux et horaires de repli.
- /api/media/site-logo : SVG servi par la même origine, cache immutable par
  version (?v=) — la redirection signée (30 min) était mise en cache 1 h.
- Réglages : champ « Langue par défaut » retiré (sans effet) ; aide de
  l'accroche ; defaultLocale facultatif dans siteSettings.save.
- Doc : chapitre 5.2 « Les réglages du site » ; raccords constructeur,
  domaine, sommaire.

